// MODEL WATERFALL — Sekuensial, satu arah
function waterfallProject(requirements) {
  const analysis  = analyze(requirements);     // Selesai 100% dulu
  const design    = design(analysis);          // Baru mulai ini
  const code      = develop(design);           // Baru mulai ini
  const tested    = test(code);               // Baru mulai ini
  return deploy(tested);                       // Rilis SEKALI di akhir
  // ⚠️ Jika requirements salah di langkah 1 = seluruh proses harus diulang!
}

// MODEL AGILE — Iteratif, inkremental
function agileProject(requirements) {
  let product = [];
  const sprints = groupIntoSprints(requirements); // Bagi ke sprint 2 minggu

  sprints.forEach(sprint => {
    const analyzed = analyze(sprint);    // Analisis mini
    const coded    = develop(analyzed);  // Coding mini
    const tested   = test(coded);       // Testing mini
    product.push(tested);               // Rilis bertahap!
    requirements = getNewFeedback();    // Kebutuhan bisa berubah tiap sprint
  });

  return product; // Produk terus berkembang berdasarkan feedback nyata
}
